/bin/zsh -c "python3 -c 'import math,json; from scipy.special import digamma; import sympy as sy
D=20000
ps=list(sy.primerange(2,1000000)); A=math.prod(1-2/p**2 for p in ps)
rs=[.01,.02,.1,.4,.7,1.]
cache={}
def integ(m,r):
 key=(m,r)
 if key in cache:return cache[key]
 z=1/(r*m)
 if z<=1:v=1/z+math.log(z)+float(sy.EulerGamma)-1.5
 else:
  n=int(z); b=n+1
  def anti(u):return -math.log(u)-(2*n+1)/u+n*(n+1)/(2*u*u)
  v=anti(b)-anti(z)+math.log(b)-digamma(b)-1/(2*b)
 cache[key]=v/m
 return v/m
def roots(p,f):
 if f==0:return (0,0) if p==2 else (1,1)
 if f==1:return (1,0) if p==2 else ((2,2) if p%4==1 else (0,0))
 return (1,0) if p in (2,3) else ((1,1) if p%3==2 else ((3,3) if pow(p-2,(p-1)//3,p)==1 else (0,0)))
vals=[[0.]*len(rs) for _ in range(3)]
for d0 in range(1,D+1):
 fac=list(sy.factorint(d0).items())
 if any(e>1 for p,e in fac):continue
 ad=math.prod(1/(p*p-2) for p,e in fac)
 for fi in range(3):
  terms=[(1,1.)]
  for p,e in fac:
   u,v=roots(p,fi); dist=[(1,v/p**2),(p,u/p-v/p**2),(p*p,1-u/p)]
   terms=[(m*t,w*z) for m,w in terms for t,z in dist if z]
  for ri,r in enumerate(rs):vals[fi][ri]+=ad*sum(w*integ(m,r) for m,w in terms)
for n,vs in zip([\"2k+1\",\"k"'^2+1","k''^3+2"],vals):print(n,[(r,A*v/r**1.5) for r,v in zip(rs,vs)])
print("D",D,"A",A)'"'"

